type HitungOngkir = (kota: string) => number;
function memoize(fn: HitungOngkir): HitungOngkir {
  const cache: [string, number][] = [];
  return (kota) => {
    const ada = cache.find(([k]) => k === kota);
    if (ada) return ada[1];
    console.log("  hitung", kota);
    const hasil = fn(kota);
    cache.push([kota, hasil]);
    return hasil;
  };
}
