function log(asli: (this: unknown, ...args: number[]) => number, ctx: ClassMethodDecoratorContext) {
  return function (this: unknown, ...args: number[]): number {
    const hasil = asli.apply(this, args);
    console.log(`${String(ctx.name)}(${args.join(", ")}) = ${hasil}`);
    return hasil;
  };
}

class Kalkulator {
  @log
  ongkir(beratKg: number, tarif: number) { return Math.ceil(beratKg) * tarif; }
}

new Kalkulator().ongkir(2.3, 9000);   // ongkir(2.3, 9000) = 27000

function harusPositif(asli: (this: unknown, n: number) => void, ctx: ClassMethodDecoratorContext) {
  return function (this: unknown, n: number): void {
    if (n <= 0) throw new Error(`${String(ctx.name)}: nilai harus positif`);
    asli.call(this, n);
  };
}

class Celengan {
  saldo = 0;
  @harusPositif
  tabung(n: number) { this.saldo += n; }
}

const c = new Celengan();
c.tabung(20000);
try { c.tabung(-5000); } catch (e) { if (e instanceof Error) console.log(e.message); }
console.log(c.saldo);
// tabung: nilai harus positif
// 20000

function cobaUlang<A extends unknown[], R>(fn: (...a: A) => R, kali: number): (...a: A) => R {
  return (...a) => {
    for (let i = 1; ; i++) {
      try {
        return fn(...a);
      } catch (e) {
        if (i >= kali) throw e;
        console.log(`percobaan ${i} gagal, ulangi`);
      }
    }
  };
}

