function digitPemeriksa(n: number): number {
  while (n >= 10) {
    let jumlah = 0;
    while (n > 0) {
      jumlah += n % 10;
      n = Math.floor(n / 10);
    }
    n = jumlah;
  }
  return n;
}

const nomor: number[] = [20260817, 9875, 7];
