const nama: string[] = ["Agus", "Bella", "Candra", "Dimas", "Eka", "Farah", "Gita", "Hendra"];

function cariNama(daftar: string[], target: string): number {
  let kiri = 0, kanan = daftar.length - 1;
  while (kiri <= kanan) {
    const tengah = Math.floor((kiri + kanan) / 2);
    const banding = daftar[tengah].localeCompare(target);
    if (banding === 0) return tengah;
    if (banding < 0) kiri = tengah + 1;
    else kanan = tengah - 1;
  }
  return -1;
}

for (const t of ["Farah", "Agus", "Zaki"]) {
  const i = cariNama(nama, t);
  console.log(t.padEnd(6), i >= 0 ? `nomor absen ${i + 1}` : "tidak terdaftar");
}

