const batasKg: number[] = [1, 3, 5, 10, 20];
const tarif: number[] = [9000, 15000, 22000, 35000, 60000];

function tarifUntuk(berat: number): number {
  let kiri = 0, kanan = batasKg.length;
  while (kiri < kanan) {
    const tengah = Math.floor((kiri + kanan) / 2);
    if (batasKg[tengah] < berat) kiri = tengah + 1;
    else kanan = tengah;
  }
  return kiri < tarif.length ? tarif[kiri] : -1;
}

for (const b of [0.8, 3, 7.5, 25]) {
  const t = tarifUntuk(b);
  console.log(`${b} kg ->`, t < 0 ? "terlalu berat, pakai kargo" : `Rp${t.toLocaleString("id-ID")}`);
}
